{{groovy}}
  import com.xpn.xwiki.api.Class;
  import com.xpn.xwiki.api.Document;
  import com.xpn.xwiki.objects.PropertyInterface;
  import com.xpn.xwiki.objects.classes.BaseClass;
  import com.xpn.xwiki.objects.classes.NumberClass;
  import com.xpn.xwiki.objects.classes.PropertyClass;
  import org.xwiki.velocity.tools.JSONTool;

  import org.apache.commons.io.IOUtils;

  import groovy.transform.Field;
  import net.sf.json.JSONNull;

  @Field final JSONTool jsontool = new JSONTool();
  @Field final String l10nUpdateMetadataClass = services.localization.render('metadatapro.updatemetadataclasssavemessage');

  boolean isTypeMismatch(String type, PropertyInterface property)
  {
    String[] typeArray = type.split("/");
    String rawType = typeArray[0];
    if (!property.getClass().getName().equals(rawType)) {
      // we check that the requested class is the same as the property class
      return true;
    }

    if (property instanceof NumberClass) {
      NumberClass numberProp = (NumberClass) property;
      // if this is a number property, we also check the number type
      return typeArray.length != 2 || !numberProp.getNumberType().equals(typeArray[1]);
    }

    return true;
  }

  private boolean addStaticListField(BaseClass baseClass, String fieldName, String prettyName,
      List<String> values, List<String> defaultValues, String displayType, boolean multiSelect)
  {
      String sep = findSep(values);
      String vals = values == null ? "" : String.join(sep, values);
      String firstDefVal = (defaultValues == null || defaultValues.isEmpty()) ? null : defaultValues.get(0);
      return baseClass.addStaticListField(fieldName, prettyName, displayType == "select" ? 1 : 20, multiSelect, false, vals,
          displayType, sep, firstDefVal);
  }

  /**
   * @return a separator that's not used in any value (best-effort)
   * @param values the values to consider
   */
  private String findSep(List<String> values)
  {
      return findSep(values, "|;,/^:&+ ", 0);
  }

  private String findSep(List<String> values, String candidateSeparators, int i)
  {
      if (i >= candidateSeparators.length()) {
          // none of the candidate separators could be found, we'll just find whichever string of '+'s suffices
          return findSepPlus(values, "++");
      }

      char candidateSeparator = candidateSeparators.charAt(i);

      for (String v : values) {
          if (v !== null && !v.isEmpty()) {
              if (v.indexOf((int) candidateSeparator) != -1) {
                  return findSep(values, candidateSeparators, ++i);
              }
          }
      }

      return String.valueOf(candidateSeparator);
  }

  private String findSepPlus(List<String> values, String candidateSeparator)
  {
      for (String v : values) {
          if (v != null && !v.isEmpty()) {
              if (v.contains(candidateSeparator)) {
                  return findSepPlus(values, candidateSeparator + '+');
              }
          }
      }

      return candidateSeparator;
  }

  void createField(BaseClass baseClass, String technicalName, String prettyName, String type, List<String> values, List<String> defaultValues)
  {
    switch (type) {
      case "StringClass":
        baseClass.addTextField(technicalName, prettyName, 255);
        return;
      case "NumberClass/long":
        baseClass.addNumberField(technicalName, prettyName, 30, "long");
        return;
      case "NumberClass/double":
        baseClass.addNumberField(technicalName, prettyName, 30, "double");
        return;
      case "PageClass/single":
        baseClass.addPageField(technicalName, prettyName, 30, false);
        return;
      case "PageClass/multi":
        baseClass.addPageField(technicalName, prettyName, 30, true);
        return;
      case "TextAreaClass":
        baseClass.addTextAreaField(technicalName, prettyName, 80, 10);
        return;
      case "BooleanClass":
        baseClass.addBooleanField(technicalName, prettyName);
        return;
      case "DateClass":
        baseClass.addDateField(technicalName, prettyName, null, 0);
        return;
      case "EmailClass":
        baseClass.addEmailField(technicalName, prettyName, 255);
        return;
      case "StaticListClass/select":
        addStaticListField(baseClass, technicalName, prettyName, values, defaultValues, "select", false);
        return;
      case "StaticListClass/checkbox":
        addStaticListField(baseClass, technicalName, prettyName, values, defaultValues, "checkbox", true);
        return;
      case "StaticListClass/radio":
        addStaticListField(baseClass, technicalName, prettyName, values, defaultValues, "radio", false);
        return;
    }
  }

  def updateFields()
  {
    Class c = doc.getxWikiClass();

    BaseClass baseClass = c.getXWikiClass();
    Collection<PropertyInterface> fieldList = new ArrayList<>(baseClass.getFieldList());
    Map<String, PropertyInterface> originalFields = new HashMap<>(fieldList.size());
    int i = 0;

    for (PropertyInterface field : fieldList) {
      // we get the fields by name and remove them from the base class
      String name = field.getName();
      originalFields.put(name, field);
      baseClass.removeField(name);
    }

    List<String> requiredFields = new ArrayList<String>();

    Map<String, Object> defaultValues = new HashMap<String, Object>();

    for (Map<String, String> field : jsontool.parse(IOUtils.toString(request.getReader()))) {
      // We add each field, in the requested order
      i++;
      String technicalName = field.get("technicalName");
      if (technicalName == null || technicalName.isEmpty()) {
        // there's a client side verification to avoid empty properties name.
        // Still, an empty name would severely break the document beyond repair
        // so we guard against this here too.
        continue;
      }
      String prettyName = field.get("prettyName");
      String type = field.get("type");
      boolean required = field.get("required");
      if (required) {
        requiredFields.add(technicalName);
      }
      PropertyInterface property = originalFields.get(technicalName);

      def dv = field.get("defaultValues");
      if (dv instanceof JSONNull) {
        dv = null;
      }

      if (dv != null && !((List)dv).isEmpty()) {
        defaultValues.put(technicalName, dv);
      }

      if (property == null || isTypeMismatch(type, property)) {
        createField(baseClass, technicalName, prettyName, type, field.get("values"), dv);
      } else {
        if (property instanceof PropertyClass) {
          PropertyClass p = (PropertyClass) property;
          if (!Objects.equals(prettyName, p.getPrettyName())) {
            p.setPrettyName(prettyName);
          }
          p.setNumber(i);
        }
        baseClass.addField(technicalName, property);
        // See https://jira.xwiki.org/browse/XWIKI-23526
        baseClass.getFieldsToRemove().remove(property);
      }
    }

    com.xpn.xwiki.api.Object object = doc.getObject("MetadataPro.Code.MetadataSetClass", true);
    object.set("requiredFields", requiredFields);
    object.set("defaultValues", jsontool.serialize(defaultValues));

    doc.save(l10nUpdateMetadataClass);
  }

  if (doc.isNew()) {
    doc.save();
    response.sendRedirect(doc.getURL())
  }

  if (request.get("action") == "update") {
    updateFields();

    response.setContentType('application/json')
    response.getWriter().write(jsontool.serialize(Map.of("ok", true)))
    xcontext.setFinished(true)
  }
{{/groovy}}

