{{groovy}}
  import com.xpn.xwiki.api.Class;
  import com.xpn.xwiki.api.Element;
  import com.xpn.xwiki.objects.classes.StaticListClass;
  import groovy.transform.Field;
  import org.xwiki.velocity.tools.JSONTool;
  import groovy.xml.XmlUtil;

  @Field final JSONTool jsontool = new JSONTool();

  @Field final Map<String, String> TYPE_FRIENDLY_NAME = [
    "StringClass": services.localization.render("metadatapro.fieldtype.string"),
    "NumberClass/long": services.localization.render("metadatapro.fieldtype.long"),
    "NumberClass/double": services.localization.render("metadatapro.fieldtype.double"),
    "TextAreaClass": services.localization.render("metadatapro.fieldtype.text"),
    "BooleanClass": services.localization.render("metadatapro.fieldtype.boolean"),
    "DateClass": services.localization.render("metadatapro.fieldtype.date"),
    "EmailClass": services.localization.render("metadatapro.fieldtype.email"),
    "StaticListClass/radio": services.localization.render("metadatapro.fieldtype.listradio"),
    "StaticListClass/select": services.localization.render("metadatapro.fieldtype.listselect"),
    "StaticListClass/checkbox": services.localization.render("metadatapro.fieldtype.listcheckbox"),
    "PageClass/single": services.localization.render("metadatapro.fieldtype.pagesingle"),
    "PageClass/multi": services.localization.render("metadatapro.fieldtype.pagemulti")
  ];

  @Field final String l10nFieldTechName = services.xml.escape(services.localization.render("metadatapro.set.th.fieldtechnicalname"));
  @Field final String l10nFieldName = services.xml.escape(services.localization.render("metadatapro.set.th.fieldname"));
  @Field final String l10nFieldType = services.xml.escape(services.localization.render("metadatapro.set.th.type"));
  @Field final String l10nRequired = services.xml.escape(services.localization.render("metadatapro.set.th.required"));
  @Field final String l10nActions = services.xml.escape(services.localization.render("metadatapro.set.th.actions"));
  @Field final String l10nTechnicalNamesCantBeEmpty = services.xml.escape(services.localization.render('metadatapro.technicalnamescantbeempty'));
  @Field final String l10nSomethingWentWrongSavingFields = services.xml.escape(services.localization.render('metadatapro.somethingwentwrongsavingfields'));
  @Field final String l10nAtLeastOneField = services.xml.escape(services.localization.render('metadatapro.atleastonefield'));

  boolean isManaged(String type)
  {
    return TYPE_FRIENDLY_NAME.containsKey(type);
  }

  String icon(String name)
  {
    return services.icon.renderHTML(name);
  }

  String renderValueInput(String value, boolean isDefault)
  {
    return (
        '<li>'
        + "<input type='checkbox' autocomplete='off' class='metadatapro-default-checkbox' title='default' aria-label='default' " + (isDefault ? "checked='checked' " : "") + "/>"
        + '<input class="metadatapro-list-value" aria-label="Allowed value" type="text" autocomplete="off" value="' + XmlUtil.escapeXml(value) + '"/>'
        + '<span>'
        +     "<button class='metadatapro-field-value-up btn-metadatapro-linklike' title='" + services.localization.render("metadatapro.actions.up") + "' aria-label='" + services.localization.render("metadatapro.actions.up") + "'>${icon('up')}</button>"
        +     " "
        +     "<button class='metadatapro-field-value-down btn-metadatapro-linklike' title='" + services.localization.render("metadatapro.actions.down") + "' aria-label='" + services.localization.render("metadatapro.actions.down") + "'>${icon('down')}</button>"
        +     " "
        +     "<button class='metadatapro-field-value-remove btn-metadatapro-linklike btn-metadatapro-delete' title='" + services.localization.render("metadatapro.actions.remove") + "' aria-label='" + services.localization.render("metadatapro.actions.remove") + "'>${icon('cross')}</button>"
        +     " "
        +     "<button class='metadatapro-field-value-add btn-metadatapro-linklike' title='" + services.localization.render("metadatapro.actions.add") + "' aria-label='" + services.localization.render("metadatapro.actions.add") + "'>${icon('add')}</button>"
        + '</span>'
        + '</li>'
      );
  }

  String renderValueInputs(List<String> values, List<Object> defaultValues)
  {
    String lis = "";
    for (String value : values) {
      lis += renderValueInput(value, defaultValues != null && defaultValues.contains(value));
    }
    return '<ul class="field-values">' + lis + '</ul>';
  }

  void printTableLine(propertyName, prettyName, propertyType, required, values, defaultValues, formName)
  {
    def t = TYPE_FRIENDLY_NAME[propertyType];
    def nameEscaped = services.xml.escape(propertyName);
    def prettyNameEscaped =  services.xml.escape(prettyName);
    println (
      "<tr class='metadatapro-field-row'>"
        + "<td>"
        + "<input type='checkbox' class='metadatapro-advanced-checkbox' aria-label='Advanced' />"
        + "</td>"
        + "<td>"
        +   "<input autocomplete='off' " + (nameEscaped.isEmpty() ? "" : "disabled='disabled' ") + "aria-label='" + l10nFieldTechName + "' type='text' name='field-technical-name' value='" + nameEscaped + "' pattern='[_a-zA-Z][_0-9a-zA-Z]*'/>"
        + "</td>"
        + "<td><input autocomplete='off' aria-label='" + l10nFieldName + "' type='text' name='field-pretty-name' value='" + prettyNameEscaped + "'/></td>"
        + "<td><select autocomplete='off' aria-label='" + l10nFieldType + "' name='field-type'>"
    );

    for (Map.Entry<String, String> typeEntry : TYPE_FRIENDLY_NAME) {
      def s = typeEntry.getKey().equals(propertyType) ? " selected='selected'" : "";
      println (
        "<option value='"
        + services.xml.escape(typeEntry.getKey())
        + "'"
        + s
        + ">"
        + typeEntry.getValue()
        + "</option>"
      );
    }
    println (
      "   </select></td>"
      +   "<td><input autocomplete='off' type='checkbox' aria-label='" + l10nRequired + "' name='field-required'" + (required ? " checked='checked'" : "") + " /></td>"
      +   "<td>"
      +     "<button class='metadatapro-field-up btn-metadatapro-linklike' title='" + services.localization.render("metadatapro.actions.up") + "' aria-label='" + services.localization.render("metadatapro.actions.up") + "'>${icon('up')}</button>"
      +     " "
      +     "<button class='metadatapro-field-down btn-metadatapro-linklike' title='" + services.localization.render("metadatapro.actions.down") + "' aria-label='" + services.localization.render("metadatapro.actions.down") + "'>${icon('down')}</button>"
      +     " "
      +     "<button class='metadatapro-field-remove btn-metadatapro-linklike btn-metadatapro-delete' title='" + services.localization.render("metadatapro.actions.remove") + "' aria-label='" + services.localization.render("metadatapro.actions.remove") + "'>${icon('cross')}</button>"
      +     " "
      +     "<button class='metadatapro-field-add btn-metadatapro-linklike' title='" + services.localization.render("metadatapro.actions.add") + "' aria-label='" + services.localization.render("metadatapro.actions.add") + "'>${icon('add')}</button>"
      +   "</td>"
      + "</tr>"
    );
    def vals = values;
    if (defaultValues != null) {
      if (vals == null) {
        vals = new ArrayList<>(defaultValues.size());
      } else {
        vals = new ArrayList(values);
      }
      for (String defaultValue : defaultValues) {
        if (!vals.contains(defaultValue)) {
          vals.add(defaultValue);
        }
      }
    }
    println (
      "<tr class='metadatapro-field-row-advanced'>"
      + "<td colspan='6'>"
      + "<div>"
      +   "<div class='metadatapro-simple-field'><p>"
      +     "<label>" + services.localization.render("metadatapro.defaultvalue") + " <input type='text' class='metadatapro-field-default-value' value='" + XmlUtil.escapeXml((defaultValues && !defaultValues.isEmpty()) ? defaultValues[0] : '') + "'/></label>"
      +   "</p></div>"
      +   "<div class='metadatapro-list-field'>"
      +     "<p>Values (check default values): </p>"
      +     renderValueInputs(vals, defaultValues)
      +     "<p>"
      +       "<button class='btn metadatapro-new-field-value-button'>"
      +         services.localization.render("metadatapro.actions.newvalue")
      +       "</button>"
      +     "</p>"
      +   "</div>"
      + "</div>"
      + "</td>"
      + "</tr>"
    );
  }

  void printTable() {
    Class c = doc.getxWikiClass();
    println "{{html clean=false}}"
    println (
      "<noscript>" + services.localization.render("metadatapro.requiresjavascript") + "</noscript>"
      + "<table id='table-metadatapro-fields'>"
      + "<tr>"
      +   "<th></th>"
      +   "<th>" + l10nFieldTechName + "</th>"
      +   "<th>" + l10nFieldName + "</th>"
      +   "<th>" + l10nFieldType + "</th>"
      +   "<th>" + l10nRequired + "</th>"
      +   "<th>" + l10nActions + "</th>"
      + "</tr>"
    )
    def i = 0;
    List<String> requiredFields = doc.getValue("requiredFields");
    def dv = doc.getValue("defaultValues");
    Map<String, Object> defaultValues = (dv && !dv.isEmpty()) ? jsontool.parse(dv) : Map.of();
    for (Element property : c.getProperties()) {
      def values = List.of();
      def type = property.type;
      if (type == "NumberClass") {
        type += "/" + property.getPropertyClass().getNumberType()
      } else if (type == "StaticListClass") {
        def bp = property.getBasePropertyClass();
        type += "/" + bp.getDisplayType();
        values = bp.getList();
      } else if (type == "PageClass") {
        type += "/" + (property.getPropertyClass().isMultiSelect() ? "multi" : "single");
      }

      if (isManaged(type)) {
        printTableLine(property.name, property.prettyName, type, requiredFields.contains(property.name), values, defaultValues.get(property.name), "form-field-" + (++i));
      }
    }
    println (
          "</table>"
        + "<p id='add-field-p'><button class='btn btn-primary' id='metadatapro-new-field-button'>" + services.localization.render("metadatapro.actions.newfield") + "</button></p>"
    );
    println "<template id='field-row-template'>";
    printTableLine("", "", "StringClass", false, List.of(), null, "");
    println "</template>";
    println "<template id='field-value-template'>";
    println renderValueInput("", false);
    println "</template>";
    println "<template id='technicalnamescantbeempty'>${l10nTechnicalNamesCantBeEmpty}</template>"
    println "<template id='somethingwentwrongsavingfields'>${l10nSomethingWentWrongSavingFields}</template>"
    println "<template id='atleastonefield'>${l10nAtLeastOneField}</template>"
    println "{{/html}}"
  }

  def mainReference = services.model.createDocumentReference('', ['MetadataPro', 'Code'], 'MetadataSetClassSheet')
  if (xcontext.action != "edit" && request.outputSyntax != 'annotatedhtml' && request.outputSyntax != 'annotatedxhtml' && (true || services.licensing.licensor.hasLicensureForEntity(mainReference))) {
    printTable();
  }
{{/groovy}}

