window.addEventListener("DOMContentLoaded", () => {
    "use strict";

    const fieldTemplate = document.getElementById("field-row-template");
    const table = document.getElementById("table-metadatapro-fields");

    function normalize(s) {
        return (
            s
                .replace(/[\s'"\-.;,:*|\[\]\(\)=+{}]+/gu, " ")
                .replace(/[àâáä]/gu, "a")
                .replace(/[úùûü]/gu, "u")
                .replace(/[ôóòö]/gu, "o")
                .replace(/[íìîï]/gu, "i")
                .replace(/[éèêë]/gu, "e")
                .replace(/œ/gu, "oe")
                .replace(/æ/gu, "ae")
                .replace(/š/gu, "s")
                .replace(/ç/gu, "c")
                .replace(/…/gu, "...")
        );
    }

    function technicalify(s) {
        // - removes accents
        // - camelify ("hello world" => "helloWorld")
        // - removes unknown characters
        // - make sure the field name doesn't start with a figure
        return normalize(s.trim())
            .replace(/[\s]+[a-zA-Z]/gu, m => m.trim().toUpperCase())
            .replace(/[^a-zA-Z0-9_"]+/gu, "_")
            .replace(/^[0-9]/, "_$0")
            .replace(/^[A-Z]/, m => m.toLowerCase());
    }

    function bindAutoTechnicalNameEvents(technicalNameInput, prettyNameInput) {
        if (technicalNameInput.disabled) {
            return;
        }
        let syncedToTechnical = false;
        let syncedToPretty = false;

        function technicalifyIfInvalid() {
            if (!technicalNameInput.checkValidity()) {
                technicalNameInput.value = technicalify(technicalNameInput.value);
            }
        }

        function updateSynced() {
            syncedToTechnical = technicalNameInput.value === ""
                || technicalNameInput.value === technicalify(prettyNameInput.value);
            syncedToPretty = prettyNameInput.value === "" || prettyNameInput.value === technicalNameInput.value;
        }

        updateSynced();

        technicalNameInput.addEventListener("keyup", () => {
            if (syncedToPretty) {
                prettyNameInput.value = technicalNameInput.value;
            }
            updateSynced();
        });

        prettyNameInput.addEventListener("keyup", () => {
            if (syncedToTechnical) {
                technicalNameInput.value = technicalify(prettyNameInput.value);
            }
            updateSynced();
        });

        technicalNameInput.addEventListener("blur", technicalifyIfInvalid);
        technicalNameInput.addEventListener("change", technicalifyIfInvalid);
    }

    function bindAutoTechnicalNameEventsTR(tr) {
        const technicalNameInput = tr.querySelector("[name='field-technical-name']");
        const prettyNameInput = tr.querySelector("[name='field-pretty-name']");
        bindAutoTechnicalNameEvents(technicalNameInput, prettyNameInput);
    }


    function bindActionEvents(tr) {
        tr.querySelector(".metadatapro-field-remove").addEventListener("click",
            () => void(tr.remove())
        );

        tr.querySelector(".metadatapro-field-up").addEventListener("click",
           () => {
                const advancedTR = tr.nextElementSibling;
                const p = tr?.previousElementSibling?.previousElementSibling;
                if (p && p.firstChild.nodeName.toLowerCase() != "th") {
                    p.before(tr);
                    tr.after(advancedTR);
                }
            }
        );

        tr.querySelector(".metadatapro-field-down").addEventListener("click",
            () => {
                const advancedTR = tr.nextElementSibling;
                const n = tr.nextElementSibling?.nextElementSibling?.nextElementSibling;
                if (n) {
                    n.after(tr);
                    tr.after(advancedTR);
                }
            }
        );

        tr.querySelector(".metadatapro-field-add").addEventListener("click", addField.bind(null, tr.nextElementSibling));
    }

    const newValueTemplate = document.getElementById("field-value-template");

    function bindValueEvents(li) {
        const addValue = li.querySelector(".metadatapro-field-value-add");
        const removeValue = li.querySelector(".metadatapro-field-value-remove");
        const up = li.querySelector(".metadatapro-field-value-up");
        const down = li.querySelector(".metadatapro-field-value-down");

        addValue.addEventListener("click", () => {
            const li = createValueInputLI();
            addValue.closest("li").after(li);
            li.querySelector("input[type=text]").focus();
        });

        removeValue.addEventListener("click", () => {
           removeValue.closest("li").remove();
        });

        up.addEventListener("click", () => {
           const li = up.closest("li");
           const p = li.previousElementSibling;
           if (p) {
               p.before(li);
           }
        });

        down.addEventListener("click", () => {
           const li = up.closest("li");
           const n = li.nextElementSibling;
           if (n) {
               n.after(li);
           }
        });

        li.querySelector("input[type='text']").addEventListener("keydown", e => {
            if (e.keyCode === 13) {
                addValue.click();
            }
        });
    }

    function createValueInputLI() {
        const newValue = newValueTemplate.content.cloneNode(true);
        bindValueEvents(newValue)
        return newValue.querySelector("li");
    }

    function bindAdvancedActionEvents(advancedFieldTR) {
        advancedFieldTR.querySelector(".metadatapro-new-field-value-button").addEventListener("click", () => {
            const li = createValueInputLI(advancedFieldTR);
            advancedFieldTR.querySelector(".field-values").append(li);
            li.querySelector("input[type='text']").focus();
        });

        for (const li of advancedFieldTR.querySelectorAll('.field-values > li')) {
            bindValueEvents(li);
        }
    }

    function bindFieldEvents(fieldTR, advancedFieldTR) {
        bindAutoTechnicalNameEventsTR(fieldTR);
        bindActionEvents(fieldTR);
        bindAdvancedActionEvents(advancedFieldTR);
    }

    async function save() {
        const fields = [];
        for (const tr of table.getElementsByClassName("metadatapro-field-row")) {
            const advancedTR = tr.nextElementSibling;

            const technicalNameInput = tr.querySelector("[name='field-technical-name']");
            const prettyNameInput    = tr.querySelector("[name='field-pretty-name']");
            const requiredInput      = tr.querySelector("[name='field-required']");
            const typeInput          = tr.querySelector("[name='field-type']");
            const defaultValueInput  = advancedTR.querySelector(".metadatapro-field-default-value");

            const technicalName = technicalNameInput.value.trim();
            if (technicalName == "") {
                alert(document.getElementById("technicalnamescantbeempty").content.textContent);
                technicalNameInput.focus();
                return;
            }

            const type = typeInput.value;

            const valueInputs = advancedTR.getElementsByClassName("metadatapro-list-value");
            const values  = [].map.call(valueInputs, input => input.value);

            const defaultValues = (type.startsWith("StaticListClass/") || type === "PageClass/multi")
                ? [].map.call(
                    advancedTR.querySelectorAll(":checked + .metadatapro-list-value"),
                    input => input.value
                )
                : (defaultValueInput.value === "" ? null : [defaultValueInput.value]);

            fields.push({
                technicalName,
                prettyName: prettyNameInput.value,
                required: requiredInput.checked,
                type,
                defaultValues: defaultValues == null ? null : (defaultValues.length > 0 ? defaultValues : null) ,
                values
            });
        }

        if (!fields.length) {
            alert(document.getElementById("atleastonefield").content.textContent);
            return;
        }

        const response = await fetch(
            location.href.split('?')[0] + "?action=update&outputSyntax=plain&xpage=plain", {
                method: "POST",
                body: JSON.stringify(fields)
            }
        );

        try {
            if (response.ok) {
                const r = await response.json();
                if (r.ok) {
                    //location.reload();
                    document.getElementById("metadatapro-save-form").submit();
                    return;
                }
            }
        } catch (e) {
            console.error("Saving failed", e);
        }

        alert(document.getElementById("somethingwentwrongsavingfields").content.textContent);
    }

    function addField(afterTR) {
        const [newTR, newAdvancedTR] = fieldTemplate.content.cloneNode(true).children;
        const tableBody = table.querySelector(":scope > tbody");
        if (afterTR) {
            afterTR.after(newTR, newAdvancedTR);
        } else {
            (tableBody || table).append(newTR, newAdvancedTR);
        }
        bindFieldEvents(newTR, newAdvancedTR);
        newTR.querySelector('input[type="text"]').focus();
    }

    function initEvents() {
        for (const tr of table.getElementsByClassName("metadatapro-field-row")) {
            bindFieldEvents(tr, tr.nextElementSibling);
        }

        document.getElementById("metadatapro-new-field-button").addEventListener("click", addField.bind(null, null));
        document.getElementById("metadatapro-save-button").addEventListener("click", save);
        document.getElementById("metadatapro-cancel-button").addEventListener("click", () => {
            location.reload();
        });
    }

    initEvents();
});

#table-metadatapro-fields {
  border-bottom:1px solid #ddd;

  > tr:first-child, > tbody > tr:first-child {
    display:none;
  }

  &:has(.metadatapro-field-row) {
    + #add-field-p {
      display: none;
    }

    > tr:first-child, > tbody > tr:first-child {
      display:table-row;
    }
  }
}

.metadatapro-list-field {
  width: 100%;
  display: none;
}

.metadatapro-simple-field {
  width: 100%;
  display: block;

  label {
    display: flex;
    gap: 1ex;
    align-items: center;

    input {
      flex: 1;
    }
  }
}

.metadatapro-field-row {
  > td {
    vertical-align: middle;
  }

  &:has([name='field-type'] > [value^="StaticListClass/"]:checked),
  &:has([name='field-type'] > [value="PageClass/multi"]:checked) {
    + tr  {
      .metadatapro-list-field {
        display: block;
      }
      .metadatapro-simple-field {
        display: none;
      }
    }
  }

  &:has(.metadatapro-advanced-checkbox:checked) + tr {
    display: table-row;
  }

  input, select {
    width: 100%;
  }
}


input.metadatapro-advanced-checkbox[type=checkbox] {
  appearance: none;
  -webkit-appearance: none;
  &:not(:checked):before {
    content: "▶";
  }
  &:checked:before {
    content: "▼";
  }
}

.metadatapro-field-row-advanced {
  display: none;

  label { font-weight: normal; }
  p { margin: 0 }

  > td > div {
    display: flex;
    flex-direction: row;
    justify-content: space-around;
    gap: 2em;
  }
}

.field-values {
  list-style: none;
  padding: 0;
  margin:0;

  &:not(:empty) + p {
    display:none;
  }

  > li {
    display: flex;
    gap: 1em;
    margin-bottom:0.5ex;

    > span {
      display: flex; /* aligns vertically */
      gap: 0.5ex;
    }

    > input[type="text"] {
      flex: 1;
    }
  }
}
